    engineeringData: { blockDesign: "Cast Iron 06A block. The BEA utilizes a massively reinforced bottom end to handle the K04 turbo.", crankshaft: "Forged Steel, supported by 5 main bearings.", pistonSpeed: "15.4 m/s @ 6000 RPM.", alternator: "120A Bosch.", rotatingAssembly: { pistonConstruction: "Forged Aluminum alloy with a lower 8.9:1 compression ratio.", wristPinDiameter: "20 mm (Reinforced over 180hp models).", connectingRodLength: "144 mm.", rodBoltSize: "M8 stretch bolts.", crankMainJournal: "54.0 mm.", crankRodJournal: "47.8 mm.", rodRatio: "1.66." }, cylinderHead: { combustionChamberVol: "Optimized 5-valve pent-roof design.", intakePortFlow: "Small port design.", valveSizes: "Intake: 3x 26.9 mm / Exhaust: 2x 29.9 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Hydraulic VVT on the intake camshaft for emissions and wideband lambda tuning.", lifterType: "Hydraulic lifters.", specialFeature: "The unique 5-valve-per-cylinder design maximizes valve curtain area." }, oilAndCooling: { oilSquirters: "Yes, dedicated under-piston cooling jets.", oilPumpType: "Chain-driven gear pump.", thermostatOpening: "87°C Mechanical.", oilCooler: "Water-to-oil heat exchanger." }, fuelSystem: { systemType: "Multi-Point Port Injection (MPI).", maxPressure: "3.0 Bar static base pressure.", injectors: "4x 386cc EV6 style injectors." }, tuningLimits: { maxSafeTorqueStock: "420 Nm.", maxSafePowerStock: "350 hp.", maxSafeRPM: "7200 RPM.", weakestLink: "Connecting rods, clutch, and small port head flow." }, electrical: { coils: "Push-down 4-wire Active Coils.", ecu: "Bosch ME7.5 Wideband." } },
