    engineeringData: { blockDesign: "Cast Iron narrow-angle (15-degree) VR6 block. Innovatively staggers 6 cylinders into a single block with a single cylinder head, saving massive engine bay space.", crankshaft: "Forged Steel, supported by 7 main bearings, offering incredible durability and distinctive harmonic balance.", pistonSpeed: "17.4 m/s @ 6300 RPM.", alternator: "120A Bosch.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy with asymmetrical crowns to account for the 15-degree bank angle.", wristPinDiameter: "20 mm.", connectingRodLength: "164 mm.", rodBoltSize: "M9 stretch bolts.", crankMainJournal: "60.0 mm.", crankRodJournal: "54.0 mm.", rodRatio: "1.95." }, cylinderHead: { combustionChamberVol: "Complex flat-head design; combustion chambers are largely formed by the piston crowns.", intakePortFlow: "Cross-flow 24-valve DOHC. Utilizes unequal length runners to feed both banks from a single side.", valveSizes: "Intake: 33.2 mm / Exhaust: 30.2 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Continuous Variable Valve Timing (VVT) on both intake and exhaust camshafts.", lifterType: "Hydraulic roller rockers.", specialFeature: "Variable intake manifold (shifter rod) optimizes runner length for low-end torque and high-end horsepower." }, oilAndCooling: { oilSquirters: "Yes, dedicated under-piston cooling jets.", oilPumpType: "Chain-driven gear pump located in the oil pan.", thermostatOpening: "80°C Mechanical.", oilCooler: "Water-to-oil heat exchanger." }, fuelSystem: { systemType: "Multi-Point Port Injection (MPI).", maxPressure: "4.0 Bar static base pressure.", injectors: "6x Bosch EV6 injectors." }, tuningLimits: { maxSafeTorqueStock: "450 Nm (NA) / 600 Nm (Turbo w/ Head Spacer).", maxSafePowerStock: "500 hp (Turbo w/ Head Spacer).", maxSafeRPM: "7000 RPM.", weakestLink: "DSG Clutch Packs, Timing Chains, Connecting Rods (Under high boost)." }, electrical: { coils: "Push-down 4-wire Active Coils.", ecu: "Bosch ME7.1.1." } },
