    engineeringData: { blockDesign: "Cast Iron EA888 Gen 2 block. Incredibly rigid and dense, but plagued by fundamental engineering flaws in the piston ring design.", crankshaft: "Forged Steel, supported by 5 main bearings.", pistonSpeed: "16.8 m/s @ 6200 RPM.", alternator: "140A Bosch.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy, utilizing incredibly thin, low-tension oil scraper rings that clog with carbon instantly.", wristPinDiameter: "21 mm.", connectingRodLength: "144 mm.", rodBoltSize: "M8 stretch bolts.", crankMainJournal: "58.0 mm.", crankRodJournal: "47.8 mm.", rodRatio: "1.66." }, cylinderHead: { combustionChamberVol: "Optimized pent-roof design.", intakePortFlow: "High-flow tumble ports optimized for FSI injection.", valveSizes: "Intake: 33.8 mm / Exhaust: 28.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Continuous Variable Valve Timing on the intake camshaft.", lifterType: "Hydraulic roller finger followers.", specialFeature: "Features an integrated exhaust manifold cooling circuit to reduce EGTs." }, oilAndCooling: { oilSquirters: "Yes, dedicated under-piston cooling jets.", oilPumpType: "Chain-driven variable displacement gear pump.", thermostatOpening: "95°C Map-controlled electronic.", oilCooler: "Water-to-oil heat exchanger." }, fuelSystem: { systemType: "FSI High Pressure Direct Injection.", maxPressure: "150 Bar.", injectors: "4x Solenoid high-speed injectors." }, tuningLimits: { maxSafeTorqueStock: "350 Nm (Limited largely by the weak DQ200 7-speed DSG if equipped).", maxSafePowerStock: "320 hp.", maxSafeRPM: "6800 RPM.", weakestLink: "Piston Rings, Timing Chain Tensioner, Plastic Water Pump." }, electrical: { coils: "Push-down 4-wire Active Coils.", ecu: "Bosch MED17.5." } },
