  engineeringData: { blockDesign: "Cast Iron EA189 block. Exceptionally robust, designed to withstand massive diesel cylinder pressures and high compression ratios.", crankshaft: "Forged Steel, supported by 5 main bearings, equipped with a geared balance shaft module in the oil pan to cancel out harsh 4-cylinder diesel vibrations.", pistonSpeed: "14.4 m/s @ 4500 RPM.", alternator: "140A Bosch.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy with internal oil cooling galleries and a specialized combustion bowl in the crown.", wristPinDiameter: "26 mm.", connectingRodLength: "144 mm.", rodBoltSize: "M9 stretch bolts.", crankMainJournal: "54.0 mm.", crankRodJournal: "50.9 mm.", rodRatio: "1.66." }, cylinderHead: { combustionChamberVol: "Flat head design; combustion occurs entirely within the piston bowl.", intakePortFlow: "16-valve DOHC. Features swirl flaps to increase air velocity and fuel atomization at low engine speeds.", valveSizes: "Intake: 28.1 mm / Exhaust: 26.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Fixed timing. Both camshafts are driven by a single toothed belt via an internal gear connection.", lifterType: "Hydraulic lifters with low-friction roller rockers.", specialFeature: "Common Rail injection drastically reduces diesel clatter compared to older Pumpe Düse (PD) designs." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-pressure under-piston cooling jets.", oilPumpType: "Gerotor pump driven by the balance shaft module via a 6mm hex key.", thermostatOpening: "87°C Mechanical.", oilCooler: "Water-to-oil heat exchanger." }, fuelSystem: { systemType: "Bosch EDC17 Common Rail.", maxPressure: "1800 Bar.", injectors: "4x Piezoelectric injectors." }, tuningLimits: { maxSafeTorqueStock: "450 Nm (Limited primarily by the dual-mass flywheel and clutch).", maxSafePowerStock: "240 hp (Requires DPF delete and turbo upgrade).", maxSafeRPM: "5000 RPM.", weakestLink: "CP4.1 Fuel Pump, Oil Pump Hex Key, Dual Mass Flywheel." }, electrical: { coils: "N/A (Compression Ignition).", ecu: "Bosch EDC17." } },
  recommendedParts: { description: "Crucial preventative maintenance parts to save the EA189 TDI block from its fatal flaws.", parts: [ { category: "CP4 Disaster Prevention Kit", brand: "Whitbread / Darkside", note: "CRITICAL: Install immediately to save injectors if the CP4 pump fails." }, { category: "Timing Belt Kit", brand: "Gates / INA", note: "Must include a metal-impeller water pump and new tensioner rollers." }, { category: "Oil Pump Hex Key", brand: "Genuine VW", note: "CRITICAL: Proactively replace the 100mm hex key to prevent engine seizure." }, { category: "Dual Mass Flywheel", brand: "LuK / Sachs", note: "Replace if a loud metallic clattering is heard at idle." }, { category: "Glow Plugs", brand: "Beru / Bosch", note: "Failed glow plugs will prevent the crucial DPF regeneration cycles." }, { category: "DPF Differential Sensor", brand: "Bosch", note: "Prone to failure, causing false DPF clogged readings." }, { category: "EGR Cooler", brand: "Pierburg", note: "Replace if unexplained coolant loss occurs without visible exterior leaks." }, { category: "DSG Filter & Fluid", brand: "Genuine Audi", note: "Strict 60k km replacement is mandatory for DQ250 longevity." } ] },
