  engineeringData: { blockDesign: "Compacted Graphite Iron (CGI) EA855 block. Exceptionally rigid, dense, and lightweight compared to standard cast iron, designed specifically to withstand the extreme cylinder pressures of the 5-cylinder turbo.", crankshaft: "Forged Steel, supported by 6 main bearings, offering incredible durability and distinctive 1-2-4-5-3 harmonic balance.", pistonSpeed: "17.1 m/s @ 6800 RPM.", alternator: "140A Bosch.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy with reinforced crowns and thick wrist pins to handle high boost.", wristPinDiameter: "22 mm.", connectingRodLength: "144 mm.", rodBoltSize: "M9 stretch bolts.", crankMainJournal: "58.0 mm.", crankRodJournal: "47.8 mm.", rodRatio: "1.66." }, cylinderHead: { combustionChamberVol: "Optimized pent-roof design.", intakePortFlow: "High-flow tumble ports optimized for FSI injection.", valveSizes: "Intake: 33.8 mm / Exhaust: 28.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Continuous Variable Valve Timing on both intake and exhaust camshafts.", lifterType: "Hydraulic roller finger followers.", specialFeature: "The legendary 5-cylinder firing order produces a unique, aggressive exhaust note reminiscent of Group B rally cars." }, oilAndCooling: { oilSquirters: "Yes, dedicated under-piston cooling jets.", oilPumpType: "Chain-driven variable displacement gear pump.", thermostatOpening: "87°C Mechanical.", oilCooler: "Large water-to-oil heat exchanger." }, fuelSystem: { systemType: "FSI High Pressure Direct Injection.", maxPressure: "130 Bar.", injectors: "5x High-flow Solenoid injectors." }, tuningLimits: { maxSafeTorqueStock: "650 Nm (DQ500 DSG can handle more with TCU tune).", maxSafePowerStock: "550 hp.", maxSafeRPM: "7200 RPM.", weakestLink: "HPFP Internals, Factory Intercooler, Manual Clutch." }, electrical: { coils: "Push-down 4-wire Active Coils.", ecu: "Bosch MED9.1.2." } },
  recommendedParts: { description: "Crucial preventative maintenance parts to maximize the performance and lifespan of the EA855 2.5 TFSI.", parts: [ { category: "Front Brake Rotors", brand: "GiroDisc / SHW Performance", note: "CRITICAL: Replaces the flawed, warping-prone factory rotors." }, { category: "Front Brake Pads", brand: "Ferodo DS2500 / EBC Yellowstuff", note: "CRITICAL: Cures the horrific factory brake squeal." }, { category: "PCV Valve Assembly", brand: "Genuine Audi", note: "Replace proactively to save the rear main seal and cure whistling." }, { category: "Ignition Coils", brand: "Eldor / NGK", note: "Upgrade to R8 'Red' coils for better spark reliability." }, { category: "Spark Plugs", brand: "NGK Racing", note: "Replace every 40k km for tuned 2.5 TFSI setups." }, { category: "HPFP Internals", brand: "Autotech", note: "Mandatory upgrade for Stage 2 or E85 tuning." }, { category: "DSG Filter & Fluid", brand: "Genuine Audi", note: "Strict 60k km replacement is mandatory for the DQ500." }, { category: "Haldex Filter & Fluid", brand: "BorgWarner", note: "Replace every 60k km to save the AWD pump." } ] },
