  engineeringData: { blockDesign: "Cast Iron EA888 Gen 3 block with exceptionally thin 3mm cylinder walls for weight reduction. Radically evolved from Gen 2, it features an exhaust manifold integrated directly into the cylinder head's cooling circuit to rapidly heat the cabin and significantly reduce Exhaust Gas Temperatures.", crankshaft: "Forged Steel, featuring 4 counterweights and supported by 5 main bearings.", pistonSpeed: "16.8 m/s @ 6200 RPM.", alternator: "140A Bosch.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy with a totally redesigned three-piece oil scraper ring that completely cures the Gen 2's notorious oil consumption flaw.", wristPinDiameter: "21 mm.", connectingRodLength: "144 mm.", rodBoltSize: "M8 stretch bolts.", crankMainJournal: "58.0 mm.", crankRodJournal: "47.8 mm.", rodRatio: "1.66." }, cylinderHead: { combustionChamberVol: "Optimized pent-roof design.", intakePortFlow: "High-flow tumble ports. The massive leap forward is the Dual Injection system (MPI+FSI), which keeps the intake valves perfectly clean and allows for massive fueling headroom.", valveSizes: "Intake: 33.8 mm / Exhaust: 28.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Continuous Variable Valve Timing on both intake and exhaust camshafts, plus Audi Valvelift System (AVS) on the exhaust side to drastically improve turbo spool.", lifterType: "Hydraulic roller finger followers.", specialFeature: "Integrated exhaust manifold drastically improves thermal management and turbo response times." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-flow under-piston cooling jets.", oilPumpType: "Chain-driven variable displacement vane pump.", thermostatOpening: "105°C Map-controlled highly complex rotary valve.", oilCooler: "Water-to-oil heat exchanger." }, fuelSystem: { systemType: "Dual Injection: FSI (High Pressure 200 Bar) + MPI (Low Pressure Port Injection).", maxPressure: "200 Bar.", injectors: "4x FSI Solenoid injectors + 4x MPI injectors." }, tuningLimits: { maxSafeTorqueStock: "450 Nm (Requires DSG TCU tune or manual clutch upgrade to hold).", maxSafePowerStock: "400 hp.", maxSafeRPM: "6800 RPM.", weakestLink: "Plastic Water Pump, IS20 Turbo Top-End Flow, Factory Intercooler." }, electrical: { coils: "Push-down 4-wire Active Coils.", ecu: "Continental SIMOS 18.1." } },
