  engineeringData: { blockDesign: "Cast Iron EA888 Gen 3 block. Features exceptionally thin 3mm cylinder walls for weight reduction and an exhaust manifold integrated directly into the cylinder head's cooling circuit to rapidly heat the cabin and reduce EGTs.", crankshaft: "Forged Steel, featuring 4 counterweights and supported by 5 main bearings.", pistonSpeed: "16.8 m/s @ 6200 RPM.", alternator: "140A Bosch.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy with the fully cured three-piece oil scraper ring design, permanently resolving oil consumption flaws.", wristPinDiameter: "21 mm.", connectingRodLength: "144 mm.", rodBoltSize: "M8 stretch bolts.", crankMainJournal: "58.0 mm.", crankRodJournal: "47.8 mm.", rodRatio: "1.66." }, cylinderHead: { combustionChamberVol: "Optimized pent-roof design.", intakePortFlow: "High-flow tumble ports. Due to Euro 6d-TEMP regulations, the MPI system was largely removed in Europe, making this a pure FSI head.", valveSizes: "Intake: 33.8 mm / Exhaust: 28.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Continuous Variable Valve Timing on both intake and exhaust camshafts, plus Audi Valvelift System (AVS) on the exhaust side to drastically improve turbo spool.", lifterType: "Hydraulic roller finger followers.", specialFeature: "Integrated exhaust manifold drastically improves thermal management and turbo response times." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-flow under-piston cooling jets.", oilPumpType: "Chain-driven variable displacement vane pump.", thermostatOpening: "105°C Map-controlled highly complex rotary valve.", oilCooler: "Water-to-oil heat exchanger." }, fuelSystem: { systemType: "FSI High Pressure Direct Injection (paired with a Gasoline Particulate Filter).", maxPressure: "250 Bar.", injectors: "4x High-pressure Solenoid injectors." }, tuningLimits: { maxSafeTorqueStock: "450 Nm (Limited primarily by GPF backpressure and DSG clutch limits).", maxSafePowerStock: "400 hp.", maxSafeRPM: "6800 RPM.", weakestLink: "Plastic Water Pump, GPF Restrictions, IS20 Turbo Top-End Flow." }, electrical: { coils: "Push-down 4-wire Active Coils.", ecu: "Continental SIMOS 18.10." } },
