  engineeringData: { blockDesign: "Cast Iron EA288 block. A massive evolution over the older EA189, designed specifically to meet Euro 6 emissions while modularizing the accessory layout.", crankshaft: "Forged Steel, supported by 5 main bearings.", pistonSpeed: "14.4 m/s @ 4500 RPM.", alternator: "140A Bosch.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy with internal oil cooling galleries and a specialized combustion bowl in the crown.", wristPinDiameter: "26 mm.", connectingRodLength: "144 mm.", rodBoltSize: "M9 stretch bolts.", crankMainJournal: "54.0 mm.", crankRodJournal: "50.9 mm.", rodRatio: "1.66." }, cylinderHead: { combustionChamberVol: "Flat head design; combustion occurs entirely within the piston bowl.", intakePortFlow: "16-valve DOHC. The EA288 integrates the valve cover and camshafts into a single non-serviceable module (cam frame).", valveSizes: "Intake: 28.1 mm / Exhaust: 26.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Fixed timing. Both camshafts are driven by a single toothed belt via an internal gear connection.", lifterType: "Hydraulic lifters with low-friction roller rockers.", specialFeature: "Integrated water-to-air intercooler directly inside the intake manifold for ultra-short charge piping and instant throttle response." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-pressure under-piston cooling jets.", oilPumpType: "Variable displacement vane pump driven by a wet-belt submerged in the oil pan (replacing the old hex-key design).", thermostatOpening: "87°C Mechanical.", oilCooler: "Water-to-oil heat exchanger." }, fuelSystem: { systemType: "Bosch EDC17 Common Rail.", maxPressure: "2000 Bar.", injectors: "4x Solenoid injectors." }, tuningLimits: { maxSafeTorqueStock: "480 Nm (Limited primarily by the dual-mass flywheel and clutch).", maxSafePowerStock: "250 hp (Requires DPF delete and turbo upgrade).", maxSafeRPM: "5000 RPM.", weakestLink: "Variable Water Pump, Dual Mass Flywheel, Intake Manifold Intercooler." }, electrical: { coils: "N/A (Compression Ignition).", ecu: "Bosch EDC17C64." } },
  recommendedParts: { description: "Crucial preventative maintenance parts to save the EA288 TDI block from its fatal flaws.", parts: [ { category: "Timing Belt Kit", brand: "Gates / INA", note: "CRITICAL: Must include a metal-impeller water pump and new tensioner." }, { category: "Water Pump (Standard)", brand: "Hepu", note: "Upgrade to a non-variable pump to avoid sticking shroud overheating." }, { category: "Expansion Tank", brand: "Genuine Audi", note: "Replace with a 'Mit Silikat' free version to save the heater core." }, { category: "Dual Mass Flywheel", brand: "LuK", note: "Replace if a loud metallic clattering is heard at idle." }, { category: "Glow Plugs", brand: "Beru / Bosch", note: "Failed glow plugs will prevent the crucial DPF regeneration cycles." }, { category: "DPF Differential Sensor", brand: "Bosch", note: "Prone to failure, causing false DPF clogged readings." }, { category: "Fuel Filter", brand: "Mann-Filter", note: "CRITICAL: Clean fuel is the only thing lubricating the high-pressure pump." }, { category: "DSG Filter & Fluid", brand: "Genuine Audi", note: "Strict 60k km replacement is mandatory for DQ250 longevity." } ] },
