    oilAndFilters: [ { interval: "10,000 km", timeLimit: "1 year", task: "Oil & Filter Change", details: "VW 507 00 synthetic strictly. Critical for DPF health and oil pump belt longevity.", parts: ["4.7L Oil", "Mann-Filter"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "80 EUR" }, { interval: "30,000 km", timeLimit: "2 years", task: "Engine Air Filter", details: "Replace paper element.", parts: ["Air Filter"], importance: "High", laborDifficulty: "Easy", estimatedCost: "25 EUR" }, { interval: "30,000 km", timeLimit: "1 year", task: "Cabin Filter", details: "Activated carbon replacement.", parts: ["Cabin Filter"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "20 EUR" }, { interval: "30,000 km", timeLimit: "2 years", task: "Fuel Filter", details: "CRITICAL: Clean fuel is the only thing lubricating the high-pressure pump.", parts: ["Fuel Filter"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "45 EUR" } ],
