  engineeringData: { blockDesign: "Aluminum EA855 Evo block. A massive evolution over the previous iron block, saving 26 kg. Exceptionally rigid and dense, designed specifically to withstand extreme cylinder pressures.", crankshaft: "Forged Steel, supported by 6 main bearings, hollow-bored to save 1 kg, offering incredible durability and the distinctive 1-2-4-5-3 harmonic balance.", pistonSpeed: "17.1 m/s @ 6800 RPM.", alternator: "140A Bosch.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy with integrated cooling channels, reinforced crowns, and thick wrist pins to handle high boost.", wristPinDiameter: "22 mm.", connectingRodLength: "144 mm.", rodBoltSize: "M9 stretch bolts.", crankMainJournal: "58.0 mm.", crankRodJournal: "47.8 mm.", rodRatio: "1.66." }, cylinderHead: { combustionChamberVol: "Optimized pent-roof design.", intakePortFlow: "High-flow tumble ports. Dual Injection (MPI+FSI) keeps the intake valves perfectly clean and provides massive fueling headroom for tuners.", valveSizes: "Intake: 33.8 mm / Exhaust: 28.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Continuous Variable Valve Timing on both intake and exhaust camshafts, plus Audi Valvelift System (AVS) on the exhaust side to drastically improve turbo spool.", lifterType: "Hydraulic roller finger followers.", specialFeature: "The legendary 5-cylinder firing order produces a unique, aggressive exhaust note reminiscent of Group B rally cars." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-flow under-piston cooling jets.", oilPumpType: "Chain-driven variable displacement vane pump.", thermostatOpening: "87°C Mechanical.", oilCooler: "Large water-to-oil heat exchanger." }, fuelSystem: { systemType: "Dual Injection: FSI (High Pressure 200 Bar) + MPI (Low Pressure Port Injection).", maxPressure: "200 Bar.", injectors: "5x High-flow FSI Solenoid injectors + 5x MPI injectors." }, tuningLimits: { maxSafeTorqueStock: "750 Nm (DQ500 DSG easily handles this with a TCU tune).", maxSafePowerStock: "700 hp.", maxSafeRPM: "7200 RPM.", weakestLink: "Front Bevel Box (Transfer Case), Factory Intercooler, Front Brakes." }, electrical: { coils: "Push-down 4-wire Active Coils.", ecu: "Bosch MED17.1.62." } },
  recommendedParts: { description: "Crucial preventative maintenance parts to maximize the performance and lifespan of the EA855 Evo 2.5 TFSI.", parts: [ { category: "Front Brake Rotors", brand: "GiroDisc / SHW Performance", note: "CRITICAL: Replaces the flawed, warping-prone factory rotors." }, { category: "Front Brake Pads", brand: "Ferodo DS2500 / EBC Yellowstuff", note: "CRITICAL: Cures the horrific factory brake squeal." }, { category: "PCV Valve Assembly", brand: "Genuine Audi", note: "Replace proactively to save the rear main seal and cure whistling." }, { category: "Ignition Coils", brand: "Eldor / NGK", note: "Upgrade to latest revision coils for better spark reliability." }, { category: "Spark Plugs", brand: "NGK Racing", note: "Replace strictly every 30k km for tuned 2.5 TFSI setups." }, { category: "Front Bevel Box Fluid", brand: "Motul / Ravenol", note: "CRITICAL: Change every 30k km to prevent transfer case explosion." }, { category: "DSG Filter & Fluid", brand: "Genuine Audi", note: "Strict 60k km replacement is mandatory for the DQ500." }, { category: "Haldex Fluid", brand: "BorgWarner", note: "Must physically remove pump to clean screen every 30k km." } ] },
