    oilAndFilters: [ { interval: "10,000 km", timeLimit: "1 year", task: "Oil & Filter Change", details: "VW 504 00 5W-30 synthetic strictly. The 5-cylinder generates massive heat.", parts: ["7.1L Oil", "Mann-Filter"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "120 EUR" }, { interval: "30,000 km", timeLimit: "2 years", task: "Engine Air Filter", details: "Replace paper element.", parts: ["Air Filter"], importance: "High", laborDifficulty: "Easy", estimatedCost: "35 EUR" }, { interval: "30,000 km", timeLimit: "1 year", task: "Cabin Filter", details: "Activated carbon replacement.", parts: ["Cabin Filter"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "20 EUR" }, { interval: "60,000 km", timeLimit: "5 years", task: "Fuel Filter", details: "Inline filter replacement.", parts: ["Fuel Filter"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "40 EUR" } ],
