  engineeringData: { blockDesign: "Aluminum EA855 Evo block. Exceptionally rigid, dense, and lightweight compared to standard cast iron, designed specifically to withstand the extreme cylinder pressures of the 5-cylinder turbo.", crankshaft: "Forged Steel, supported by 6 main bearings, hollow-bored to save 1 kg, offering incredible durability and the distinctive 1-2-4-5-3 harmonic balance.", pistonSpeed: "17.1 m/s @ 6800 RPM.", alternator: "140A Bosch.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy with integrated cooling channels, reinforced crowns, and thick wrist pins to handle high boost.", wristPinDiameter: "22 mm.", connectingRodLength: "144 mm.", rodBoltSize: "M9 stretch bolts.", crankMainJournal: "58.0 mm.", crankRodJournal: "47.8 mm.", rodRatio: "1.66." }, cylinderHead: { combustionChamberVol: "Optimized pent-roof design.", intakePortFlow: "High-flow tumble ports. Due to strict Euro 6d-TEMP regulations, the DNWA is typically a pure FSI head, relying on OPF filters for emissions compliance.", valveSizes: "Intake: 33.8 mm / Exhaust: 28.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Continuous Variable Valve Timing on both intake and exhaust camshafts, plus Audi Valvelift System (AVS) on the exhaust side to drastically improve turbo spool.", lifterType: "Hydraulic roller finger followers.", specialFeature: "The legendary 5-cylinder firing order produces a unique, aggressive exhaust note reminiscent of Group B rally cars, though slightly muted by the GPF compared to the DAZA." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-flow under-piston cooling jets.", oilPumpType: "Chain-driven variable displacement vane pump.", thermostatOpening: "87°C Mechanical.", oilCooler: "Large water-to-oil heat exchanger." }, fuelSystem: { systemType: "FSI High Pressure Direct Injection (often paired with Gasoline Particulate Filters).", maxPressure: "250 Bar.", injectors: "5x High-flow Solenoid injectors." }, tuningLimits: { maxSafeTorqueStock: "750 Nm (Limited primarily by GPF backpressure and DSG clutch limits).", maxSafePowerStock: "700 hp.", maxSafeRPM: "7200 RPM.", weakestLink: "Front Bevel Box (Transfer Case), Factory Intercooler, GPF Restrictions." }, electrical: { coils: "Push-down 4-wire Active Coils.", ecu: "Bosch MED17.1.62." } },
  recommendedParts: { description: "Crucial preventative maintenance parts to maximize the performance and lifespan of the EA855 Evo 2.5 TFSI.", parts: [ { category: "Front Brake Rotors", brand: "GiroDisc / SHW Performance", note: "CRITICAL: Replaces the flawed, warping-prone factory rotors." }, { category: "Front Brake Pads", brand: "Ferodo DS2500 / EBC Yellowstuff", note: "CRITICAL: Cures the horrific factory brake squeal." }, { category: "PCV Valve Assembly", brand: "Genuine Audi", note: "Replace proactively to save the rear main seal and cure whistling." }, { category: "Ignition Coils", brand: "Eldor / NGK", note: "Upgrade to latest revision coils for better spark reliability." }, { category: "Spark Plugs", brand: "NGK Racing", note: "Replace strictly every 30k km for tuned 2.5 TFSI setups." }, { category: "Front Bevel Box Fluid", brand: "Motul / Ravenol", note: "CRITICAL: Change every 30k km to prevent transfer case explosion." }, { category: "DSG Filter & Fluid", brand: "Genuine Audi", note: "Strict 60k km replacement is mandatory for the DQ500." }, { category: "Haldex Fluid", brand: "BorgWarner", note: "Must physically remove pump to clean screen every 30k km." } ] },
