  engineeringData: { blockDesign: "All-Aluminum 90-degree V8. Exceptionally lightweight and compact. Utilizes an advanced dry-sump lubrication system with an external oil tank to ensure uninterrupted oil pressure during high-G cornering and to allow the engine to sit incredibly low in the chassis.", crankshaft: "Forged Steel, cross-plane design, supported by 5 main bearings.", pistonSpeed: "22.6 m/s @ 8250 RPM (Extremely high piston speed, rivaling dedicated race engines).", alternator: "190A Bosch, liquid-cooled.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy with highly specialized asymmetrical skirts to accommodate the compact block design.", wristPinDiameter: "22 mm.", connectingRodLength: "154 mm.", rodBoltSize: "M9 stretch bolts.", crankMainJournal: "65.0 mm.", crankRodJournal: "54.0 mm.", rodRatio: "1.66." }, cylinderHead: { combustionChamberVol: "Optimized pent-roof design tailored for the ultra-high 12.5:1 compression ratio.", intakePortFlow: "High-flow tumble ports. Pure FSI direct injection is utilized, making the heads extremely susceptible to carbon buildup.", valveSizes: "Intake: 33.9 mm / Exhaust: 28.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Continuous Variable Valve Timing on all four camshafts.", lifterType: "Hydraulic roller finger followers.", specialFeature: "Magnesium alloy valve covers to save weight." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-flow under-piston cooling jets.", oilPumpType: "Multi-stage chain-driven gear pump for the complex dry-sump system.", thermostatOpening: "90°C Mechanical.", oilCooler: "Massive twin air-to-oil heat exchangers mounted in the front bumper side vents." }, fuelSystem: { systemType: "FSI High Pressure Direct Injection.", maxPressure: "120 Bar.", injectors: "8x High-pressure Solenoid injectors." }, tuningLimits: { maxSafeTorqueStock: "650 Nm.", maxSafePowerStock: "650 hp (Supercharged).", maxSafeRPM: "8500 RPM.", weakestLink: "Manual Clutch, Factory Connecting Rods (under high boost)." }, electrical: { coils: "Push-down 4-wire Active Coils.", ecu: "Dual Bosch MED9.1 (Master/Slave)." } },
  recommendedParts: { description: "Crucial preventative maintenance parts to maximize the performance and lifespan of the mid-engine V8.", parts: [ { category: "Engine Oil Filter", brand: "Mahle / Audi Genuine", note: "CRITICAL: Ensure proper dry-sump oil fill procedure is followed." }, { category: "Spark Plugs", brand: "NGK PFR7S8EG", note: "Replace every 40k km; the high-revving V8 consumes plugs quickly." }, { category: "Ignition Coils", brand: "Eldor / Audi Genuine", note: "Prone to failure from extreme mid-engine bay heat." }, { category: "Engine Air Filters", brand: "BMC / K&N", note: "Requires two filters; high-flow drop-ins slightly improve throttle response." }, { category: "S-Tronic ATF Fluid", brand: "Genuine Audi", note: "Mandatory 60k km replacement for DL800 mechatronic survival." }, { category: "PCV Valve", brand: "Genuine Audi", note: "Replace proactively to prevent massive vacuum leaks." }, { category: "Intake Manifold Gaskets", brand: "Elring", note: "Mandatory replacement during the 50k km walnut blasting service." }, { category: "Magnetic Ride Delete Kit", brand: "KW Suspensions", note: "Required when converting from leaking factory Delphi shocks to passive coilovers." } ] },
