    oilAndFilters: [ { interval: "10,000 km", timeLimit: "1 year", task: "Dry Sump Oil & Filter Change", details: "VW 504 00 synthetic strictly. Must drain tank and block plugs. MUST check level while engine is running at temperature.", parts: ["9.5L Oil", "Filter Cartridge"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "180 EUR" }, { interval: "30,000 km", timeLimit: "2 years", task: "Dual Engine Air Filters", details: "Replace both paper elements in the carbon fiber airboxes.", parts: ["2x Air Filters"], importance: "High", laborDifficulty: "Easy", estimatedCost: "80 EUR" }, { interval: "30,000 km", timeLimit: "1 year", task: "Cabin Filter", details: "Activated carbon replacement.", parts: ["Cabin Filter"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "40 EUR" }, { interval: "60,000 km", timeLimit: "5 years", task: "Fuel Filter", details: "Inline filter replacement.", parts: ["Fuel Filter"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "60 EUR" } ],
