  engineeringData: { blockDesign: "All-Aluminum 90-degree V10. Based directly on the Lamborghini Gallardo LP560-4 architecture. Utilizes an advanced dry-sump lubrication system with an external oil tank to ensure uninterrupted oil pressure during high-G cornering.", crankshaft: "Forged Steel, supported by 6 main bearings, featuring a common pin design that creates the iconic uneven firing order and F1-style exhaust note.", pistonSpeed: "22.0 m/s @ 8700 RPM (Extremely high piston speed, rivaling dedicated race engines).", alternator: "190A Bosch, liquid-cooled.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy with highly specialized asymmetrical skirts to accommodate the compact block design.", wristPinDiameter: "22 mm.", connectingRodLength: "154 mm.", rodBoltSize: "M9 stretch bolts.", crankMainJournal: "65.0 mm.", crankRodJournal: "54.0 mm.", rodRatio: "1.66." }, cylinderHead: { combustionChamberVol: "Optimized pent-roof design tailored for the ultra-high 12.5:1 compression ratio.", intakePortFlow: "High-flow tumble ports. Pure FSI direct injection is utilized, making the heads extremely susceptible to carbon buildup.", valveSizes: "Intake: 33.9 mm / Exhaust: 28.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Continuous Variable Valve Timing on all four camshafts.", lifterType: "Hydraulic roller finger followers.", specialFeature: "Magnesium alloy valve covers to save weight." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-flow under-piston cooling jets.", oilPumpType: "Multi-stage chain-driven gear pump for the complex dry-sump system.", thermostatOpening: "90°C Mechanical.", oilCooler: "Massive twin air-to-oil heat exchangers mounted in the front bumper side vents." }, fuelSystem: { systemType: "FSI High Pressure Direct Injection.", maxPressure: "120 Bar.", injectors: "10x High-pressure Solenoid injectors." }, tuningLimits: { maxSafeTorqueStock: "800 Nm (Requires upgraded clutch).", maxSafePowerStock: "850 hp (Twin Turbo).", maxSafeRPM: "8800 RPM.", weakestLink: "R-tronic Clutch, Factory Connecting Rods (under extreme turbo boost)." }, electrical: { coils: "Push-down 4-wire Active Coils.", ecu: "Dual Bosch MED9.1 (Master/Slave)." } },
  recommendedParts: { description: "Crucial preventative maintenance parts to maximize the performance and lifespan of the mid-engine V10.", parts: [ { category: "Engine Oil Filter", brand: "Mahle / Audi Genuine", note: "CRITICAL: Ensure proper dry-sump oil fill procedure is followed." }, { category: "Spark Plugs", brand: "NGK PFR7S8EG", note: "Replace every 40k km; the high-revving V10 consumes plugs quickly." }, { category: "Ignition Coils", brand: "Eldor / Audi Genuine", note: "Prone to failure from extreme mid-engine bay heat." }, { category: "Engine Air Filters", brand: "BMC / K&N", note: "Requires two filters; high-flow drop-ins slightly improve throttle response." }, { category: "R-tronic Clutch Kit", brand: "Valeo / Audi Genuine", note: "Requires rear subframe removal for installation." }, { category: "PCV Valve", brand: "Genuine Audi", note: "Replace proactively to prevent massive vacuum leaks." }, { category: "Intake Manifold Gaskets", brand: "Elring", note: "Mandatory replacement during the 50k km walnut blasting service." }, { category: "Magnetic Ride Delete Kit", brand: "KW Suspensions", note: "Required when converting from leaking factory Delphi shocks to passive coilovers." } ] },
  maintenanceSchedule: {
    fluidsAndDrivetrain: [ { interval: "30,000 km", timeLimit: "3 years", task: "R-tronic / Manual Gearbox Oil", details: "Drain and refill the Graziano transaxle.", parts: ["4.0L 75W-90 GL-4/5"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "160 EUR" }, { interval: "30,000 km", timeLimit: "3 years", task: "R-tronic Hydraulic Fluid", details: "Flush the high-pressure actuator fluid.", parts: ["1.0L G 004 000 M2"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "200 EUR" }, { interval: "60,000 km", timeLimit: "5 years", task: "Front Differential Oil", details: "Drain and fill front transfer case.", parts: ["1.0L 75W-90 GL-5"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "90 EUR" }, { interval: "2 Years", timeLimit: "2 years", task: "Brake Fluid Flush", details: "Flush DOT 4 Low Viscosity fluid.", parts: ["1.0L DOT 4 LV"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "100 EUR" } ],
    oilAndFilters: [ { interval: "10,000 km", timeLimit: "1 year", task: "Dry Sump Oil & Filter Change", details: "VW 504 00 synthetic strictly. Must drain tank and block plugs. MUST check level while engine is running at temperature.", parts: ["10.0L Oil", "Filter Cartridge"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "200 EUR" }, { interval: "30,000 km", timeLimit: "2 years", task: "Dual Engine Air Filters", details: "Replace both paper elements in the carbon fiber airboxes.", parts: ["2x Air Filters"], importance: "High", laborDifficulty: "Easy", estimatedCost: "80 EUR" }, { interval: "30,000 km", timeLimit: "1 year", task: "Cabin Filter", details: "Activated carbon replacement.", parts: ["Cabin Filter"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "40 EUR" }, { interval: "60,000 km", timeLimit: "5 years", task: "Fuel Filter", details: "Inline filter replacement.", parts: ["Fuel Filter"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "60 EUR" } ],
    ignitionAndEngine: [ { interval: "40,000 km", timeLimit: "4 years", task: "Spark Plugs", details: "Replace to prevent misfires at 8500+ RPM.", parts: ["10x NGK Plugs"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "200 EUR" }, { interval: "80,000 km", timeLimit: "8 years", task: "Ignition Coils", details: "Proactive replacement to prevent high-load misfires.", parts: ["10x Coils"], importance: "High", laborDifficulty: "Easy", estimatedCost: "400 EUR" }, { interval: "50,000 km", timeLimit: "N/A", task: "Walnut Blasting", details: "CRITICAL: Remove intake manifold and physically blast carbon from all 10 intake ports. Restores 30-50 lost horsepower.", parts: ["Intake Gaskets", "Walnut Media"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "1000 EUR" }, { interval: "60,000 km", timeLimit: "N/A", task: "PCV Valve", details: "Replacement to prevent rear main seal blowout.", parts: ["PCV Assembly"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "150 EUR" } ],
    preventiveAndSuspension: [ { interval: "80,000 km", timeLimit: "N/A", task: "Magnetic Ride Check", details: "Inspect electronic Delphi dampers for fluid leaks. Prepare for highly expensive replacement or coilover conversion.", parts: ["Diagnostic"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "0 EUR" }, { interval: "60,000 km", timeLimit: "N/A", task: "R-tronic Clutch Snap Check", details: "Use VCDS to measure remaining clutch wear. Replacement requires exhaust and bumper removal.", parts: ["Diagnostic"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "0 EUR" } ],
    coolingAndHvac: [ { interval: "100,000 km", timeLimit: "5 years", task: "Coolant Flush", details: "Drain and refill massive 23-liter G12++ system.", parts: ["23.0L G12++"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "160 EUR" }, { interval: "4 Years", timeLimit: "4 years", task: "A/C Recharge", details: "Evacuate and recharge R134a.", parts: ["Refrigerant"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "150 EUR" } ],
    engineMechanical: [ { interval: "150,000 km", timeLimit: "N/A", task: "Timing Chain Inspection", details: "Check camshaft phase adaptation via VCDS. If chains are severely stretched, an engine-out service is required.", parts: ["Diagnostic"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "0 EUR" }, { interval: "100,000 km", timeLimit: "N/A", task: "A/C Compressor Shaft Inspection", details: "Listen for whining noises from the gear-driven A/C unit.", parts: ["Diagnostic"], importance: "High", laborDifficulty: "Easy", estimatedCost: "0 EUR" } ]
  },
