    ignitionAndEngine: [ { interval: "40,000 km", timeLimit: "4 years", task: "Spark Plugs", details: "Replace with platinum/iridium plugs.", parts: ["10x Plugs"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "280 EUR" }, { interval: "80,000 km", timeLimit: "8 years", task: "Ignition Coils", details: "Proactive replacement for high-RPM reliability.", parts: ["10x Coils"], importance: "High", laborDifficulty: "Easy", estimatedCost: "450 EUR" }, { interval: "100,000 km", timeLimit: "None", task: "Serpentine Belt", details: "Replace belt and inspect tensioner/pulleys.", parts: ["Belt", "Tensioner"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "150 EUR" } ],
    preventiveAndSuspension: [ { interval: "15,000 km", timeLimit: "None", task: "Rear Tire Inspection", details: "Check tread depth; RWD models wear rears extremely fast.", parts: ["Visual Inspection Tool"], importance: "High", laborDifficulty: "Easy", estimatedCost: "0 EUR" }, { interval: "50,000 km", timeLimit: "None", task: "Magnetic Ride Inspection", details: "Check for weeping fluid on all four corners.", parts: ["Diagnostic Tool"], importance: "High", laborDifficulty: "Easy", estimatedCost: "0 EUR" }, { interval: "100,000 km", timeLimit: "None", task: "Control Arm Bushings", details: "Inspect aluminum arms for rubber tearing.", parts: ["Bushings"], importance: "Medium", laborDifficulty: "Advanced", estimatedCost: "600 EUR" } ],
