  sisterModels: [ { name: "Lamborghini Huracán LP580-2", note: "The R8 V10 RWD is the mechanical twin to the Huracán RWD, sharing the identical engine, transaxle, and chassis architecture." } ],
  tuningPotential: [
    { stage: "Stage 1", power: "580 - 610 hp", notes: "The RWD model is software-detuned from the factory. A simple software flash unlocks the full potential of the V10, allowing it to match or exceed the Performance AWD models. Transforms the car's top-end character.", zeroToHundred: "3.4s", hundredToTwoHundred: "7.2s" },
    { stage: "Stage 2", power: "630 - 650 hp", notes: "Requires high-flow catalytic converters and a performance exhaust. The engine screams past 8,800 RPM and delivers a more aggressive torque curve that demands high-quality rear tires.", zeroToHundred: "3.2s", hundredToTwoHundred: "6.9s" },
    { stage: "Stage 3 (Twin Turbo)", power: "800 - 1,000+ hp", notes: "The ultimate V10 experience. Bolt-on turbo kits from companies like VF Engineering or Underground Racing. The stock block is legendary for its ability to hold four-digit horsepower figures.", zeroToHundred: "2.6s", hundredToTwoHundred: "4.2s" }
  ],
