  engineeringData: { blockDesign: "Aluminum-Silicon (Alusil) 90-degree V10. Naturally aspirated with a dry-sump lubrication system utilizing 4 scavenge pumps to ensure oil pressure at over 1.2G of lateral acceleration.", crankshaft: "Forged Steel, cross-plane with a shared crankpin design, resulting in the signature V10 harmonic howl and immense structural rigidity.", pistonSpeed: "22.8 m/s @ 8700 RPM (One of the highest piston speeds in any production car).", alternator: "210A Bosch.", rotatingAssembly: { pistonConstruction: "Forged Aluminum alloy with hard-anodized ring grooves and friction-reducing coating.", wristPinDiameter: "22 mm.", connectingRodLength: "154 mm.", rodBoltSize: "M10 high-tensile.", crankMainJournal: "65.0 mm.", crankRodJournal: "54.0 mm.", rodRatio: "1.66." }, cylinderHead: { combustionChamberVol: "Optimized pent-roof design for high-tumble flow.", intakePortFlow: "High-velocity runners. Dual Injection (MPI+FSI) ensures the intake valves stay clean for the life of the engine.", valveSizes: "Intake: 34.5 mm / Exhaust: 28.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Fully variable timing on both intake and exhaust via hydraulic phasers.", lifterType: "Hydraulic roller finger followers.", specialFeature: "Cylinder on Demand (CoD) can deactivate one bank to turn the engine into a 2.6L inline-5 for efficiency." }, oilAndCooling: { oilSquirters: "Yes, dual-jet under-piston cooling.", oilPumpType: "Map-controlled variable pressure gear pump.", thermostatOpening: "87°C Electronic.", oilCooler: "Twin side-mounted air-to-oil heat exchangers." }, fuelSystem: { systemType: "Dual Injection: FSI (High Pressure 200 Bar) + MPI (Low Pressure Port Injection).", maxPressure: "200 Bar.", injectors: "10x FSI Solenoid + 10x MPI injectors." }, tuningLimits: { maxSafeTorqueStock: "800 Nm.", maxSafePowerStock: "900 hp (Turbo/Supercharged).", maxSafeRPM: "8850 RPM.", weakestLink: "DL800 Clutch Packs (Above 800Nm), A/C Compressor." }, electrical: { coils: "Push-down 4-wire Active Coils.", ecu: "Dual Bosch MED17.1.1." } },
  recommendedParts: { description: "Crucial parts to maintain the health and performance of the 5.2 V10.", parts: [ { category: "Engine Oil Filter", brand: "Mahle / Audi Genuine", note: "Always replace during the 10,000 km dry-sump service." }, { category: "Spark Plugs", brand: "NGK Laser Platinum", note: "Replace every 40k km; crucial for high-RPM stability." }, { category: "Ignition Coils", brand: "Eldor", note: "Upgrade to latest revision to prevent top-end misfires." }, { category: "S-Tronic Fluid & Filter", brand: "Genuine Audi", note: "Strict 60k km interval is the only way to save the mechatronics." }, { category: "Engine Air Filters", brand: "BMC", note: "High-flow drop-ins offer a better induction sound and slightly better response." }, { category: "Cabin Filter", brand: "Mann-Filter (FreciousPlus)", note: "Biofunctional filter for the best cabin air quality." }, { category: "PCV Valve", brand: "Genuine Audi", note: "Replace proactively to prevent massive vacuum leaks." }, { category: "Serpentine Belt", brand: "Continental", note: "Inspect for cracking every 30k km due to engine bay heat." } ] },
