    engineMechanical: [ { interval: "150,000 km", timeLimit: "10 years", task: "Timing Chain Inspection", details: "Check camshaft phase adaptation via VCDS. The Gen 2 V10 chain design is highly durable, but verification is critical.", parts: ["Diagnostic Tool"], importance: "High", laborDifficulty: "Easy", estimatedCost: "80 EUR" }, { interval: "100,000 km", timeLimit: "8 years", task: "A/C Compressor Shaft Inspection", details: "Listen for whining noises from the gear-driven A/C unit.", parts: ["Diagnostic Tool"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "150 EUR" } ]
