    oilAndFilters: [ { interval: "10,000 km", timeLimit: "1 year", task: "Dry Sump Oil & Filter Change", details: "Strictly VW 508 00 0W-20 for OPF compatibility. Must follow warm-fill check procedure.", parts: ["8.3L Oil", "Mann-Filter"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "250 EUR" }, { interval: "30,000 km", timeLimit: "2 years", task: "Engine Air Filters", details: "Replace both high-volume filters.", parts: ["2x Air Filters"], importance: "High", laborDifficulty: "Easy", estimatedCost: "120 EUR" }, { interval: "30,000 km", timeLimit: "1 year", task: "Cabin Filter", details: "Activated carbon replacement.", parts: ["Cabin Filter"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "45 EUR" } ],
    ignitionAndEngine: [ { interval: "40,000 km", timeLimit: "4 years", task: "Spark Plugs", details: "Replace with platinum/iridium plugs.", parts: ["10x Plugs"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "280 EUR" }, { interval: "80,000 km", timeLimit: "8 years", task: "Ignition Coils", details: "Proactive replacement for high-RPM reliability.", parts: ["10x Coils"], importance: "High", laborDifficulty: "Easy", estimatedCost: "450 EUR" }, { interval: "100,000 km", timeLimit: "10 years", task: "Serpentine Belt", details: "Replace belt and inspect tensioner/pulleys.", parts: ["Belt", "Tensioner"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "150 EUR" } ],
